from datetime import datetime, timezone


def tumbling_counts(timestamps, minutes=15):
    size = minutes * 60
    counts = {}
    for ts in timestamps:
        seconds = int(datetime.fromisoformat(ts).timestamp())
        start = datetime.fromtimestamp(seconds - seconds % size, tz=timezone.utc)
        key = start.isoformat()
        counts[key] = counts.get(key, 0) + 1
    return counts

