import re

LINE = re.compile(r"^(\S+) ([A-Z]+) (/[^\s?]*)(\?\S*)? (\d{3}) (\d+)ms$")


def slowest_endpoints(lines, k=2):
    durations = {}
    skipped = 0
    for line in lines:
        match = LINE.match(line.strip())
        if match is None:
            skipped += 1
            continue
        endpoint = f"{match[2]} {match[3]}"
        durations.setdefault(endpoint, []).append(int(match[6]))
    p95 = {}
    for endpoint, values in durations.items():
        values.sort()
        rank = -(-95 * len(values) // 100)
        p95[endpoint] = values[rank - 1]
    top = sorted(p95.items(), key=lambda kv: (-kv[1], kv[0]))[:k]
    return {"top": [list(pair) for pair in top], "skipped": skipped}

def merge_streams(a, b):
    missing = object()
    x, y = next(a, missing), next(b, missing)
    while x is not missing and y is not missing:
        if x <= y:
            yield x
            x = next(a, missing)
        else:
            yield y
            y = next(b, missing)
    while x is not missing:
        yield x
        x = next(a, missing)
    while y is not missing:
        yield y
        y = next(b, missing)

